import base64, pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parent
if not (ROOT / ".git").exists():
    print("❌ 이 파일을 C:\\knexm-site 폴더(홈페이지 프로젝트 폴더) 안에 넣고 실행해 주세요.")
    sys.exit(1)

BOOK = ROOT / "book"
FILES = {
    "index.html": '<!doctype html>\n<html lang="ko">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>장사 말고 경영 · 구매자 특전</title>\n<meta name="description" content="《장사 말고 경영》 구매자 특전 사장님 경영 엑셀 내려받기">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700;900&display=swap" rel="stylesheet">\n<style>\n:root{--or:#D45A22;--ink:#1A1A1A;--sub:#5E5850;--line:#E6E1D9;--cream:#F8F5F0}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--cream);color:var(--ink);font-family:\'Noto Sans KR\',sans-serif;line-height:1.6;word-break:keep-all}\n.wrap{max-width:560px;margin:0 auto;padding:40px 16px 56px}\n.tag{display:inline-block;background:var(--or);color:#fff;font-size:13px;font-weight:700;padding:5px 12px;border-radius:999px}\nh1{margin:18px 0 0;font-size:40px;font-weight:900;line-height:1.15;letter-spacing:-0.03em}\nh1 em{font-style:normal;color:var(--or)}\n.sub{margin:8px 0 0;color:var(--sub);font-size:16px}\n.card{margin-top:28px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px 20px}\n.card h2{margin:0 0 6px;font-size:19px}\n.card p{margin:0;color:var(--sub);font-size:15px}\n.btns{display:flex;flex-direction:column;gap:12px;margin-top:18px}\n.btn{display:flex;align-items:center;justify-content:space-between;gap:12px;text-decoration:none;border-radius:12px;padding:16px 18px;font-weight:700;font-size:16px}\n.btn small{display:block;font-weight:400;font-size:13px;margin-top:2px}\n.btn.main{background:var(--or);color:#fff}\n.btn.main small{color:#FCE6D9}\n.btn.sec{background:#fff;color:var(--ink);border:1.5px solid var(--ink)}\n.btn.sec small{color:var(--sub)}\n.btn span.arrow{font-size:22px;line-height:1}\nol{margin:12px 0 0;padding-left:20px;color:var(--ink);font-size:15px}\nol li{margin:4px 0}\n.note{margin-top:22px;font-size:13px;color:var(--sub)}\n.foot{margin-top:36px;padding-top:16px;border-top:1px solid var(--line);font-size:13px;color:var(--sub)}\n.foot a{color:var(--sub)}\n</style>\n</head>\n<body>\n<main class="wrap">\n<span class="tag">구매자 특전</span>\n<h1>장사 말고<br><em>경영</em></h1>\n<p class="sub">작은 가게가 오래 살아남는 법 · 윤여울 지음</p>\n\n<section class="card">\n<h2>사장님 경영 엑셀</h2>\n<p>노란 칸에 숫자만 넣으면 자동으로 계산됩니다. 매출 기록, 손익분기점, 가격 계산, 상품 네 칸, 통장 나누기, 현금 흐름, 세금 달력, 간편장부, 세금 미리보기까지 9가지가 들어 있어요.</p>\n<div class="btns">\n<a class="btn main" href="ceo-excel-blank.xlsx" download="사장님 경영 엑셀_빈 양식.xlsx"><div>빈 양식 내려받기<small>우리 가게 숫자를 직접 적는 파일</small></div><span class="arrow">↓</span></a>\n<a class="btn sec" href="ceo-excel-example.xlsx" download="사장님 경영 엑셀_예시.xlsx"><div>예시판 내려받기<small>책 속 예시 숫자로 사용법을 먼저 보는 파일</small></div><span class="arrow">↓</span></a>\n</div>\n</section>\n\n<section class="card">\n<h2>이렇게 시작하세요</h2>\n<ol>\n<li>예시판을 열어 어떻게 계산되는지 먼저 봅니다.</li>\n<li>빈 양식의 <b>1번 매출기록</b>부터 한 달 동안 써 봅니다.</li>\n<li>한 달이 쌓이면 손익분기점과 상품 네 칸을 채워 봅니다.</li>\n</ol>\n<p class="note">엑셀이 없다면 구글 시트에 올려서 써도 됩니다. 계산은 경영 판단을 돕는 참고용이며, 실제 세금 신고는 홈택스 안내나 세무 전문가와 확인하세요.</p>\n</section>\n\n<p class="foot">© 윤여울 · <a href="/">케이넥스엠주식회사 KNEXM Co., Ltd.</a></p>\n</main>\n</body>\n</html>\n'.encode("utf-8"),
    "ceo-excel-example.xlsx": base64.b64decode(""),
    "ceo-excel-blank.xlsx": base64.b64decode(""),
}

same = all((BOOK / n).exists() and (BOOK / n).read_bytes() == d for n, d in FILES.items())
if same:
    print("이미 적용돼 있어요. (book 폴더에 같은 파일이 있습니다)")
    sys.exit(0)

BOOK.mkdir(exist_ok=True)
print("✔ book 폴더 준비")
for name, data in FILES.items():
    (BOOK / name).write_bytes(data)
    print(f"✔ book/{name} 저장 ({len(data):,} 바이트)")
print("\n완료! 커밋·푸시하면 https://knexm.com/book/ 에서 열립니다.")
